apiVersion: v2
name: handstack
description: Production-ready distributed deployment for HandStack
type: application
version: 0.1.0
appVersion: '0.1.0'
keywords:
  - ai
  - agents
  - gateway
maintainers:
  - name: HandStack maintainers

# HandStack Helm chart

This chart installs the distributed profile: stateless Web/API/MCP Deployments and Services,
six independently scalable worker classes, HPA, optional KEDA ScaledObjects, PDBs,
NetworkPolicies, ServiceAccount, ConfigMap and optional Ingress.

Production requires an external secret named by `externalSecrets.secretName` containing
`database-url` and `redis-url`. Set `externalSecrets.createSecret=true` only for controlled
evaluation environments; do not put production credentials in Helm values or release history.

The supported primary database adapters are `postgresql`, `mysql`, `mariadb`, `mssql` and
`mongodb`. Redis must be managed or HA (Sentinel/Cluster) in distributed production.

Example:

```sh
helm upgrade --install handstack deploy/helm/handstack \
  --set database.adapter=postgresql \
  --set externalSecrets.secretName=handstack-runtime \
  --set ingress.enabled=true
```

Use immutable image tags and a metrics-server plus an external-metrics adapter for the API/MCP HPA
signals (requests, latency, event-loop lag, active streams and in-flight capability executions).
Install KEDA separately before enabling
`keda.enabled`. Validate with `helm lint deploy/helm/handstack` and render with
`helm template handstack deploy/helm/handstack` before applying to a cluster.

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "properties": {
    "deploymentProfile": { "const": "distributed" },
    "database": {
      "type": "object",
      "properties": {
        "adapter": { "enum": ["postgresql", "mysql", "mariadb", "mssql", "mongodb"] },
        "url": { "type": "string" }
      },
      "required": ["adapter", "url"]
    },
    "objectStorage": {
      "type": "object",
      "properties": {
        "endpoint": { "type": "string" },
        "bucket": { "type": "string", "minLength": 1 }
      },
      "required": ["endpoint", "bucket"]
    },
    "queue": {
      "type": "object",
      "properties": {
        "redisUrl": { "type": "string" },
        "topology": { "enum": ["sentinel", "cluster", "managed"] }
      },
      "required": ["redisUrl", "topology"]
    },
    "externalSecrets": {
      "type": "object",
      "properties": {
        "enabled": { "type": "boolean" },
        "createSecret": { "type": "boolean" },
        "secretName": { "type": "string", "minLength": 1 }
      },
      "required": ["enabled", "createSecret", "secretName"]
    }
  },
  "required": ["deploymentProfile", "database", "objectStorage", "queue", "externalSecrets"]
}

nameOverride: ''
fullnameOverride: ''

images:
  api:
    repository: ghcr.io/handstack/api
    tag: '0.1.0'
    pullPolicy: IfNotPresent
  web:
    repository: ghcr.io/handstack/web
    tag: '0.1.0'
    pullPolicy: IfNotPresent
  worker:
    repository: ghcr.io/handstack/worker
    tag: '0.1.0'
    pullPolicy: IfNotPresent
imagePullSecrets: []

deploymentProfile: distributed
database:
  adapter: postgresql
  url: ''
objectStorage:
  endpoint: ''
  bucket: handstack
queue:
  redisUrl: ''
  topology: sentinel
externalSecrets:
  enabled: true
  secretName: handstack-external
  createSecret: false
  annotations: {}

serviceAccount:
  create: true
  automount: false
  annotations: {}

api:
  replicas: 3
  port: 3001
  resources:
    requests: { cpu: 100m, memory: 256Mi }
    limits: { cpu: '1', memory: 1Gi }
web:
  replicas: 2
  port: 3000
  resources:
    requests: { cpu: 100m, memory: 128Mi }
    limits: { cpu: '1', memory: 512Mi }
mcp:
  enabled: true
  replicas: 2
  port: 3001
  resources:
    requests: { cpu: 100m, memory: 256Mi }
    limits: { cpu: '1', memory: 1Gi }

workers:
  agents: { enabled: true, replicas: 1, queue: agents }
  knowledge: { enabled: true, replicas: 1, queue: embeddings }
  integrations: { enabled: true, replicas: 1, queue: plugins }
  webhooks: { enabled: true, replicas: 1, queue: webhooks }
  auditBilling: { enabled: true, replicas: 1, queue: audit }
  maintenance: { enabled: true, replicas: 1, queue: cleanup }
  resources:
    requests: { cpu: 100m, memory: 128Mi }
    limits: { cpu: '1', memory: 512Mi }

autoscaling:
  enabled: true
  api:
    minReplicas: 3
    maxReplicas: 50
    targetCPUUtilizationPercentage: 65
    externalMetrics:
      - { name: handstack_http_requests_per_second, type: AverageValue, value: '100' }
      - { name: handstack_http_request_p95_latency_seconds, type: AverageValue, value: '0.5' }
      - { name: handstack_event_loop_lag_seconds, type: AverageValue, value: '0.1' }
      - { name: handstack_in_flight_capability_executions, type: AverageValue, value: '20' }
  web: { minReplicas: 2, maxReplicas: 20, targetCPUUtilizationPercentage: 65 }
  mcp:
    minReplicas: 2
    maxReplicas: 30
    targetCPUUtilizationPercentage: 65
    externalMetrics:
      - { name: handstack_active_streams, type: AverageValue, value: '20' }
      - { name: handstack_http_requests_per_second, type: AverageValue, value: '100' }
      - { name: handstack_http_request_p95_latency_seconds, type: AverageValue, value: '0.5' }
      - { name: handstack_event_loop_lag_seconds, type: AverageValue, value: '0.1' }
      - { name: handstack_in_flight_capability_executions, type: AverageValue, value: '20' }
keda:
  enabled: true
  minReplicaCount: 1
  maxReplicaCount: 100
  listLength: '20'
pdb:
  enabled: true
  minAvailable: 1
ingress:
  enabled: false
  className: ''
  annotations: {}
  host: handstack.example.com
  tls: []
networkPolicy:
  enabled: true
  allowedExternalCIDRs: []
  databaseCIDRs: []
  redisCIDRs: []
  objectStorageCIDRs: []
  allowDNS: true
  allowDatabase: true
  allowRedis: true
topologySpread: true
terminationGracePeriodSeconds:
  services: 30
  workers: 60
podSecurityContext:
  runAsNonRoot: true
  seccompProfile: { type: RuntimeDefault }
containerSecurityContext:
  allowPrivilegeEscalation: false
  readOnlyRootFilesystem: true
  capabilities: { drop: [ALL] }

{{- $root := . }}
{{- $services := dict "api" .Values.api "web" .Values.web }}
{{- if .Values.mcp.enabled }}{{- $_ := set $services "mcp" .Values.mcp }}{{- end }}
{{- range $name, $cfg := $services }}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "handstack.fullname" $root }}-{{ $name }}
  labels:
    {{- include "handstack.labels" $root | nindent 4 }}
    app.kubernetes.io/component: {{ $name }}
spec:
  replicas: {{ $cfg.replicas }}
  strategy:
    type: RollingUpdate
    rollingUpdate: { maxUnavailable: 0, maxSurge: 1 }
  selector:
    matchLabels:
      {{- include "handstack.selector" $root | nindent 6 }}
      app.kubernetes.io/component: {{ $name }}
  template:
    metadata:
      labels:
        {{- include "handstack.selector" $root | nindent 8 }}
        app.kubernetes.io/component: {{ $name }}
    spec:
      serviceAccountName: {{ include "handstack.serviceAccountName" $root }}
      automountServiceAccountToken: {{ $root.Values.serviceAccount.automount }}
      terminationGracePeriodSeconds: {{ $root.Values.terminationGracePeriodSeconds.services }}
      {{- with $root.Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      securityContext:
        {{- toYaml $root.Values.podSecurityContext | nindent 8 }}
      affinity:
        podAntiAffinity:
          requiredDuringSchedulingIgnoredDuringExecution:
            - labelSelector:
                matchLabels:
                  app.kubernetes.io/component: {{ $name }}
              topologyKey: topology.kubernetes.io/zone
      {{- if $root.Values.topologySpread }}
      topologySpreadConstraints:
        - maxSkew: 1
          topologyKey: topology.kubernetes.io/zone
          whenUnsatisfiable: DoNotSchedule
          labelSelector:
            matchLabels:
              {{- include "handstack.selector" $root | nindent 14 }}
              app.kubernetes.io/component: {{ $name }}
      {{- end }}
      containers:
        - name: {{ $name }}
          image: {{ if eq $name "web" }}{{ $root.Values.images.web.repository }}:{{ $root.Values.images.web.tag }}{{ else }}{{ $root.Values.images.api.repository }}:{{ $root.Values.images.api.tag }}{{ end }}
          {{ if eq $name "mcp" }}args: ["mcp-server"]{{ end }}
          imagePullPolicy: {{ if eq $name "web" }}{{ $root.Values.images.web.pullPolicy }}{{ else }}{{ $root.Values.images.api.pullPolicy }}{{ end }}
          securityContext:
            {{- toYaml $root.Values.containerSecurityContext | nindent 12 }}
          ports:
            - name: http
              containerPort: {{ $cfg.port }}
          envFrom:
            - configMapRef: { name: {{ include "handstack.fullname" $root }}-config }
          {{- if ne $name "web" }}
            - secretRef: { name: {{ include "handstack.secretName" $root }} }
          {{- end }}
          {{- if eq $name "web" }}
          env:
            - name: HANDSTACK_API_URL
              value: http://{{ include "handstack.fullname" $root }}-api:{{ $root.Values.api.port }}
          {{- end }}
          {{- include "handstack.probes" (dict "port" "http") | nindent 10 }}
          resources:
            {{- toYaml $cfg.resources | nindent 12 }}
---
{{- end }}

{{- range $name, $cfg := .Values.workers }}
{{- if and (ne $name "resources") $cfg.enabled }}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "handstack.fullname" $root }}-worker-{{ kebabcase $name }}
  labels:
    {{- include "handstack.labels" $root | nindent 4 }}
    app.kubernetes.io/component: worker-{{ kebabcase $name }}
spec:
  replicas: {{ $cfg.replicas }}
  strategy: { type: RollingUpdate, rollingUpdate: { maxUnavailable: 0, maxSurge: 1 } }
  selector:
    matchLabels:
      {{- include "handstack.selector" $root | nindent 6 }}
      app.kubernetes.io/component: worker-{{ kebabcase $name }}
  template:
    metadata:
      labels:
        {{- include "handstack.selector" $root | nindent 8 }}
        app.kubernetes.io/component: worker-{{ kebabcase $name }}
    spec:
      serviceAccountName: {{ include "handstack.serviceAccountName" $root }}
      automountServiceAccountToken: {{ $root.Values.serviceAccount.automount }}
      terminationGracePeriodSeconds: {{ $root.Values.terminationGracePeriodSeconds.workers }}
      securityContext:
        {{- toYaml $root.Values.podSecurityContext | nindent 8 }}
      affinity:
        podAntiAffinity:
          requiredDuringSchedulingIgnoredDuringExecution:
            - labelSelector:
                matchLabels:
                  app.kubernetes.io/component: worker-{{ kebabcase $name }}
              topologyKey: topology.kubernetes.io/zone
      {{- if $root.Values.topologySpread }}
      topologySpreadConstraints:
        - maxSkew: 1
          topologyKey: topology.kubernetes.io/zone
          whenUnsatisfiable: DoNotSchedule
          labelSelector:
            matchLabels:
              {{- include "handstack.selector" $root | nindent 14 }}
              app.kubernetes.io/component: worker-{{ kebabcase $name }}
      {{- end }}
      containers:
        - name: worker
          image: {{ $root.Values.images.worker.repository }}:{{ $root.Values.images.worker.tag }}
          imagePullPolicy: {{ $root.Values.images.worker.pullPolicy }}
          args: [{{ $name | quote }}]
          securityContext:
            {{- toYaml $root.Values.containerSecurityContext | nindent 12 }}
          envFrom:
            - configMapRef: { name: {{ include "handstack.fullname" $root }}-config }
            - secretRef: { name: {{ include "handstack.secretName" $root }} }
          livenessProbe: { exec: { command: ["sh", "-c", "kill -0 1"] }, periodSeconds: 20 }
          readinessProbe: { exec: { command: ["sh", "-c", "kill -0 1"] }, periodSeconds: 10 }
          resources:
            {{- toYaml $root.Values.workers.resources | nindent 12 }}
---
{{- end }}
{{- end }}

{{- if .Values.autoscaling.enabled }}
{{- $root := . }}
{{- range $name := list "api" "web" }}
apiVersion: autoscaling/v2
kind: HorizontalPodAutoscaler
metadata:
  name: {{ include "handstack.fullname" $root }}-{{ $name }}
  labels:
    {{- include "handstack.labels" $root | nindent 4 }}
spec:
  scaleTargetRef: { apiVersion: apps/v1, kind: Deployment, name: {{ include "handstack.fullname" $root }}-{{ $name }} }
  minReplicas: {{ (index $root.Values.autoscaling $name).minReplicas }}
  maxReplicas: {{ (index $root.Values.autoscaling $name).maxReplicas }}
  metrics:
    - type: Resource
      resource:
        name: cpu
        target: { type: Utilization, averageUtilization: {{ (index $root.Values.autoscaling $name).targetCPUUtilizationPercentage }} }
{{- if eq $name "api" }}
{{- range (index $root.Values.autoscaling $name).externalMetrics }}
    - type: External
      external:
        metric: { name: {{ .name }} }
        target: { type: {{ .type }}, averageValue: {{ .value | quote }} }
{{- end }}
{{- end }}
---
{{- end }}
{{- if .Values.mcp.enabled }}
apiVersion: autoscaling/v2
kind: HorizontalPodAutoscaler
metadata:
  name: {{ include "handstack.fullname" . }}-mcp
  labels:
    {{- include "handstack.labels" . | nindent 4 }}
spec:
  scaleTargetRef: { apiVersion: apps/v1, kind: Deployment, name: {{ include "handstack.fullname" . }}-mcp }
  minReplicas: {{ .Values.autoscaling.mcp.minReplicas }}
  maxReplicas: {{ .Values.autoscaling.mcp.maxReplicas }}
  metrics:
    - type: Resource
      resource:
        name: cpu
        target: { type: Utilization, averageUtilization: {{ .Values.autoscaling.mcp.targetCPUUtilizationPercentage }} }
{{- range .Values.autoscaling.mcp.externalMetrics }}
    - type: External
      external:
        metric: { name: {{ .name }} }
        target: { type: {{ .type }}, averageValue: {{ .value | quote }} }
{{- end }}
{{- end }}
{{- end }}

{{- if .Values.keda.enabled }}
{{- $root := . }}
{{- range $name, $cfg := .Values.workers }}
{{- if and (ne $name "resources") $cfg.enabled }}
apiVersion: keda.sh/v1alpha1
kind: ScaledObject
metadata:
  name: {{ include "handstack.fullname" $root }}-worker-{{ kebabcase $name }}
  labels:
    {{- include "handstack.labels" $root | nindent 4 }}
spec:
  scaleTargetRef: { name: {{ include "handstack.fullname" $root }}-worker-{{ kebabcase $name }} }
  minReplicaCount: {{ $root.Values.keda.minReplicaCount }}
  maxReplicaCount: {{ $root.Values.keda.maxReplicaCount }}
  pollingInterval: 15
  cooldownPeriod: 60
  triggers:
    - type: redis
      metadata:
        addressFromEnv: HANDSTACK_REDIS_URL
        listName: {{ $cfg.queue | quote }}
        listLength: {{ $root.Values.keda.listLength | quote }}
{{- if not (eq $name "maintenance") }}
---
{{- end }}
{{- end }}
{{- end }}
{{- end }}

{{- if .Values.networkPolicy.enabled }}
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: {{ include "handstack.fullname" . }}-default-deny
  labels:
    {{- include "handstack.labels" . | nindent 4 }}
spec:
  podSelector: {}
  policyTypes: [Ingress, Egress]
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: {{ include "handstack.fullname" . }}-internal
spec:
  podSelector:
    matchLabels:
      {{- include "handstack.selector" . | nindent 6 }}
  policyTypes: [Ingress, Egress]
  ingress:
    - from:
        - podSelector:
            matchLabels:
              {{- include "handstack.selector" . | nindent 14 }}
  egress:
    - to:
        - podSelector:
            matchLabels:
              {{- include "handstack.selector" . | nindent 14 }}
      ports:
        - { protocol: TCP, port: 3000 }
        - { protocol: TCP, port: 3001 }
{{- if .Values.networkPolicy.allowDNS }}
    - to:
        - namespaceSelector: {}
      ports:
        - { protocol: UDP, port: 53 }
        - { protocol: TCP, port: 53 }
{{- end }}
{{- with .Values.networkPolicy.allowedExternalCIDRs }}
    - to:
        {{- range . }}
        - ipBlock: { cidr: {{ . | quote }} }
        {{- end }}
{{- end }}
{{- range $cidrs := list .Values.networkPolicy.databaseCIDRs .Values.networkPolicy.redisCIDRs .Values.networkPolicy.objectStorageCIDRs }}
{{- with $cidrs }}
    - to:
        {{- range . }}
        - ipBlock: { cidr: {{ . | quote }} }
        {{- end }}
{{- end }}
{{- end }}
{{- end }}

apiVersion: v1
kind: ConfigMap
metadata:
  name: {{ include "handstack.fullname" . }}-config
  labels:
    {{- include "handstack.labels" . | nindent 4 }}
data:
  HANDSTACK_DEPLOYMENT_PROFILE: {{ .Values.deploymentProfile | quote }}
  HANDSTACK_DATABASE_ADAPTER: {{ .Values.database.adapter | quote }}
  HANDSTACK_REDIS_TOPOLOGY: {{ .Values.queue.topology | quote }}
  HANDSTACK_OBJECT_STORAGE_ENDPOINT: {{ .Values.objectStorage.endpoint | quote }}
  HANDSTACK_OBJECT_STORAGE_BUCKET: {{ .Values.objectStorage.bucket | quote }}
  HANDSTACK_API_PORT: {{ .Values.api.port | quote }}
  HANDSTACK_MCP_PORT: {{ .Values.mcp.port | quote }}

{{- if and .Values.externalSecrets.enabled .Values.externalSecrets.createSecret }}
apiVersion: v1
kind: Secret
metadata:
  name: {{ include "handstack.secretName" . }}
  labels:
    {{- include "handstack.labels" . | nindent 4 }}
  {{- with .Values.externalSecrets.annotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
type: Opaque
stringData:
  database-url: {{ required "database.url is required when externalSecrets.createSecret=true" .Values.database.url | quote }}
  redis-url: {{ required "queue.redisUrl is required when externalSecrets.createSecret=true" .Values.queue.redisUrl | quote }}
{{- end }}

{{- $root := . }}
{{- range $name, $cfg := dict "api" .Values.api "web" .Values.web }}
apiVersion: v1
kind: Service
metadata:
  name: {{ include "handstack.fullname" $root }}-{{ $name }}
  labels:
    {{- include "handstack.labels" $root | nindent 4 }}
    app.kubernetes.io/component: {{ $name }}
spec:
  type: ClusterIP
  selector:
    {{- include "handstack.selector" $root | nindent 4 }}
    app.kubernetes.io/component: {{ $name }}
  ports:
    - name: http
      port: {{ $cfg.port }}
      targetPort: http
---
{{- end }}
{{- if .Values.mcp.enabled }}
apiVersion: v1
kind: Service
metadata:
  name: {{ include "handstack.fullname" . }}-mcp
  labels:
    {{- include "handstack.labels" . | nindent 4 }}
    app.kubernetes.io/component: mcp
spec:
  selector:
    {{- include "handstack.selector" . | nindent 4 }}
    app.kubernetes.io/component: mcp
  ports:
    - name: http
      port: {{ .Values.mcp.port }}
      targetPort: http
{{- end }}

{{- if .Values.pdb.enabled }}
{{- $root := . }}
{{- range $name := list "api" "web" }}
apiVersion: policy/v1
kind: PodDisruptionBudget
metadata:
  name: {{ include "handstack.fullname" $root }}-{{ $name }}
spec:
  minAvailable: {{ $root.Values.pdb.minAvailable }}
  selector:
    matchLabels:
      {{- include "handstack.selector" $root | nindent 6 }}
      app.kubernetes.io/component: {{ $name }}
---
{{- end }}
{{- if .Values.mcp.enabled }}
apiVersion: policy/v1
kind: PodDisruptionBudget
metadata:
  name: {{ include "handstack.fullname" . }}-mcp
spec:
  minAvailable: {{ .Values.pdb.minAvailable }}
  selector:
    matchLabels:
      {{- include "handstack.selector" . | nindent 6 }}
      app.kubernetes.io/component: mcp
{{- end }}
{{- end }}

{{- define "handstack.name" -}}
{{- default .Chart.Name .Values.nameOverride | trunc 63 | trimSuffix "-" -}}
{{- end -}}
{{- define "handstack.fullname" -}}
{{- if .Values.fullnameOverride }}{{ .Values.fullnameOverride | trunc 63 | trimSuffix "-" }}{{- else }}{{ include "handstack.name" . }}{{- end -}}
{{- end -}}
{{- define "handstack.labels" -}}
helm.sh/chart: {{ .Chart.Name }}-{{ .Chart.Version | replace "+" "_" }}
app.kubernetes.io/name: {{ include "handstack.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
app.kubernetes.io/managed-by: {{ .Release.Service }}
{{- end -}}
{{- define "handstack.selector" -}}
app.kubernetes.io/name: {{ include "handstack.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
{{- end -}}
{{- define "handstack.secretName" -}}
{{- if .Values.externalSecrets.secretName }}{{ .Values.externalSecrets.secretName }}{{- else }}{{ include "handstack.fullname" . }}-secrets{{- end -}}
{{- end -}}
{{- define "handstack.serviceAccountName" -}}
{{- if .Values.serviceAccount.create }}{{ include "handstack.fullname" . }}{{- else }}default{{- end -}}
{{- end -}}
{{- define "handstack.env" -}}
- name: HANDSTACK_DEPLOYMENT_PROFILE
  value: {{ .Values.deploymentProfile | quote }}
- name: HANDSTACK_DATABASE_ADAPTER
  value: {{ .Values.database.adapter | quote }}
- name: HANDSTACK_REDIS_TOPOLOGY
  value: {{ .Values.queue.topology | quote }}
- name: HANDSTACK_DATABASE_URL
  valueFrom: { secretKeyRef: { name: {{ include "handstack.secretName" . }}, key: database-url } }
- name: HANDSTACK_REDIS_URL
  valueFrom: { secretKeyRef: { name: {{ include "handstack.secretName" . }}, key: redis-url } }
{{- end -}}
{{- define "handstack.probes" -}}
readinessProbe:
  httpGet: { path: /health/ready, port: {{ .port }} }
  periodSeconds: 10
  failureThreshold: 3
livenessProbe:
  httpGet: { path: /health/live, port: {{ .port }} }
  periodSeconds: 20
  failureThreshold: 3
{{- end -}}
{{- define "handstack.spread" -}}
{{- if .Values.topologySpread }}
topologySpreadConstraints:
  - maxSkew: 1
    topologyKey: topology.kubernetes.io/zone
    whenUnsatisfiable: ScheduleAnyway
    labelSelector: { matchLabels: {{ include "handstack.selector" . | nindent 26 }} }
{{- end -}}
{{- end -}}

{{- if and .Values.externalSecrets.enabled .Values.externalSecrets.createSecret }}
apiVersion: v1
kind: Secret
metadata:
  name: {{ include "handstack.secretName" . }}
  labels:
    {{- include "handstack.labels" . | nindent 4 }}
  {{- with .Values.externalSecrets.annotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
type: Opaque
stringData:
  database-url: {{ required "database.url is required when externalSecrets.createSecret=true" .Values.database.url | quote }}
  redis-url: {{ required "queue.redisUrl is required when externalSecrets.createSecret=true" .Values.queue.redisUrl | quote }}
{{- end }}

{{- $root := . }}
{{- $services := dict "api" .Values.api "web" .Values.web }}
{{- if .Values.mcp.enabled }}{{- $_ := set $services "mcp" .Values.mcp }}{{- end }}
{{- range $name, $cfg := $services }}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "handstack.fullname" $root }}-{{ $name }}
  labels:
    {{- include "handstack.labels" $root | nindent 4 }}
    app.kubernetes.io/component: {{ $name }}
spec:
  replicas: {{ $cfg.replicas }}
  strategy:
    type: RollingUpdate
    rollingUpdate: { maxUnavailable: 0, maxSurge: 1 }
  selector:
    matchLabels:
      {{- include "handstack.selector" $root | nindent 6 }}
      app.kubernetes.io/component: {{ $name }}
  template:
    metadata:
      labels:
        {{- include "handstack.selector" $root | nindent 8 }}
        app.kubernetes.io/component: {{ $name }}
    spec:
      serviceAccountName: {{ include "handstack.serviceAccountName" $root }}
      automountServiceAccountToken: {{ $root.Values.serviceAccount.automount }}
      terminationGracePeriodSeconds: {{ $root.Values.terminationGracePeriodSeconds.services }}
      {{- with $root.Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      securityContext:
        {{- toYaml $root.Values.podSecurityContext | nindent 8 }}
      affinity:
        podAntiAffinity:
          requiredDuringSchedulingIgnoredDuringExecution:
            - labelSelector:
                matchLabels:
                  app.kubernetes.io/component: {{ $name }}
              topologyKey: topology.kubernetes.io/zone
      {{- if $root.Values.topologySpread }}
      topologySpreadConstraints:
        - maxSkew: 1
          topologyKey: topology.kubernetes.io/zone
          whenUnsatisfiable: DoNotSchedule
          labelSelector:
            matchLabels:
              {{- include "handstack.selector" $root | nindent 14 }}
              app.kubernetes.io/component: {{ $name }}
      {{- end }}
      containers:
        - name: {{ $name }}
          image: {{ if eq $name "web" }}{{ $root.Values.images.web.repository }}:{{ $root.Values.images.web.tag }}{{ else }}{{ $root.Values.images.api.repository }}:{{ $root.Values.images.api.tag }}{{ end }}
          {{ if eq $name "mcp" }}args: ["mcp-server"]{{ end }}
          imagePullPolicy: {{ if eq $name "web" }}{{ $root.Values.images.web.pullPolicy }}{{ else }}{{ $root.Values.images.api.pullPolicy }}{{ end }}
          securityContext:
            {{- toYaml $root.Values.containerSecurityContext | nindent 12 }}
          ports:
            - name: http
              containerPort: {{ $cfg.port }}
          envFrom:
            - configMapRef: { name: {{ include "handstack.fullname" $root }}-config }
          {{- if ne $name "web" }}
            - secretRef: { name: {{ include "handstack.secretName" $root }} }
          {{- end }}
          {{- if eq $name "web" }}
          env:
            - name: HANDSTACK_API_URL
              value: http://{{ include "handstack.fullname" $root }}-api:{{ $root.Values.api.port }}
          {{- end }}
          {{- include "handstack.probes" (dict "port" "http") | nindent 10 }}
          resources:
            {{- toYaml $cfg.resources | nindent 12 }}
---
{{- end }}

{{- range $name, $cfg := .Values.workers }}
{{- if and (ne $name "resources") $cfg.enabled }}
apiVersion: apps/v1
kind: Deployment
metadata:
